import re
from decimal import Decimal, ROUND_HALF_UP

_NUM = r"\d+(?:\.\d+)?"

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_COMPONENT_RE = re.compile(r"\s*(%s)\s*([A-Za-z]+)" % _NUM)
_FULL_COMPONENTS_RE = re.compile(r"(?:\s*%s\s*[A-Za-z]+)+\s*" % _NUM)
_INT_RE = re.compile(r"\d+")
_ISO_RE = re.compile(
    r"P(?:(%s)W)?(?:(%s)D)?(?:T(?:(%s)H)?(?:(%s)M)?(?:(%s)S)?)?" % ((_NUM,) * 5),
    re.IGNORECASE,
)
_CLOCK_RE = re.compile(r"\d+(?::\d+){1,2}")


def _round(total: Decimal) -> int:
    return int(total.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if _INT_RE.fullmatch(s):
        return int(s)

    if s[0] in "Pp":
        m = _ISO_RE.fullmatch(s)
        if not m or not any(m.groups()):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        if s.endswith("T") or s.endswith("t"):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        factors = (604800, 86400, 3600, 60, 1)
        total = Decimal(0)
        for val, f in zip(m.groups(), factors):
            if val is not None:
                total += Decimal(val) * f
        return _round(total)

    if ":" in s:
        if not _CLOCK_RE.fullmatch(s):
            raise ValueError(f"invalid clock duration: {text!r}")
        parts = [int(p) for p in s.split(":")]
        total = 0
        for p in parts:
            total = total * 60 + p
        return total

    if not _FULL_COMPONENTS_RE.fullmatch(s):
        raise ValueError(f"invalid duration: {text!r}")
    total = Decimal(0)
    pos = 0
    while pos < len(s):
        m = _COMPONENT_RE.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        num, unit = m.group(1), m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {unit!r} in {text!r}")
        total += Decimal(num) * _UNITS[unit]
        pos = m.end()
        while pos < len(s) and s[pos].isspace():
            pos += 1
    return _round(total)

